@wraps.example:
from functools import wraps
def deco(f):
    @wraps(f)
    def w(): return f()
    return w
@deco
def hi(): pass
print(hi.__name__)

@total_ordering.example:
from functools import *
@total_ordering
class A:
    def __init__(s, v): s.v = v
    def __eq__(s, o):
        return s.v == o.v
    def __lt__(s, o):
        return s.v < o.v
print(A(3) >= A(2))

